// ---------------------------------------------------------------------------
// getUser() de-duplication.
//
// Hundreds of hooks call `supabase.auth.getUser()` on mount. Each call is a
// network round-trip to /auth/v1/user, so heavy pages (Safety, Wellness, AI
// chats) fire dozens of them at once on mobile. Under that burst the auth
// endpoint can rate-limit / time out, supabase-js treats the reply as an
// invalid session and emits SIGNED_OUT — the user sees a brief "logged out"
// flash before the session is restored.
//
// Fix: coalesce concurrent calls, cache the result briefly, and short-circuit
// to the locally stored session when there is none. The cache is invalidated
// on every auth state change, so sign-in/sign-out stay instant.
// ---------------------------------------------------------------------------
const _origGetUser = supabase.auth.getUser.bind(supabase.auth);
const GET_USER_TTL_MS = 30_000;
let _userCache: { at: number; res: any } | null = null;
let _userInflight: Promise<any> | null = null;

(supabase.auth as any).getUser = async (jwt?: string) => {
  // Explicit-token checks must always hit the server.
  if (jwt) return _origGetUser(jwt);

  const now = Date.now();
  if (_userCache && now - _userCache.at < GET_USER_TTL_MS) return _userCache.res;
  if (_userInflight) return _userInflight;

  _userInflight = (async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        const res = { data: { user: null }, error: null };
        _userCache = { at: Date.now(), res };
        return res;
      }
      const res = await _origGetUser();
      if (!res?.error) _userCache = { at: Date.now(), res };
      return res;
    } finally {
      _userInflight = null;
    }
  })();

  return _userInflight;
};

supabase.auth.onAuthStateChange(() => {
  _userCache = null;
});

// ---------------------------------------------------------------------------
// Cloudflare R2 upload interception.
//
// Every `supabase.storage.from(bucket).upload(path, file)` call in the app is
// transparently routed to Cloudflare R2 (via the `upload-to-r2` edge function)
// when VITE_USE_R2_UPLOADS is enabled. The object key mirrors the Supabase
// layout (`<bucket>/<path>`), and `getPublicUrl` / `createSignedUrl` return the
// R2 public URL for objects that were uploaded there — so components that read
// uploaded files keep working without changes.
//
// Any failure falls back to the original Supabase Storage upload, so no flow
// can break because of R2.
// ---------------------------------------------------------------------------
const R2_ENABLED = import.meta.env.VITE_USE_R2_UPLOADS === "true";

async function r2UploadViaEdge(bucket: string, path: string, body: any, contentType?: string) {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session?.access_token) throw new Error("no session");

  const file =
    body instanceof File
      ? body
      : new File([body], path.split("/").pop() || "upload", {
          type: contentType || (body as Blob)?.type || "application/octet-stream" });

  const form = new FormData();
  form.append("file", file);
  form.append("key", `${bucket}/${path.replace(/^\/+/, "")}`);
  form.append("pathPrefix", bucket);

  const res = await fetch(`${SUPABASE_URL}/functions/v1/upload-to-r2`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${session.access_token}`,
      apikey: SUPABASE_PUBLISHABLE_KEY },
    body: form });

  if (!res.ok) throw new Error(`r2 ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const json = await res.json();
  if (!json?.url) throw new Error("r2 returned no url");
  return json as { url: string; key: string; bucket: string };
}

